ST.xhtml:p:
(*横梁避让轴自整定*)
CASE nMoveSelfTuningState OF 
  0:
    IF bMoveSelfTuningStart THEN
      nMoveSelfTuningState := 10;
      bMoveSelfTuningStart := FALSE;
      g_bBeamAvoidAxisSelfTuningDone := FALSE;
    END_IF;
  10:
    g_BeamAvoidAxisSelfTuning.EXECUTE := TRUE;
    g_BeamAvoidAxisSelfTuning.DIRECTION :=1;
    IF g_BeamAvoidAxisSelfTuning.DONE THEN
      g_BeamAvoidAxisSelfTuning.EXECUTE := FALSE;
      g_dBeamAvoidAxisSelfTuningCF := g_BeamAvoidAxisSelfTuning.CF_POSITIVE;
      nMoveSelfTuningState := 0;
      g_bBeamAvoidAxisSelfTuningDone := TRUE;
    END_IF;
    IF g_BeamAvoidAxisSelfTuning.COMMANDABORTED OR g_BeamAvoidAxisSelfTuning.ERROR THEN
      nMoveSelfTuningState := 20;
      g_BeamAvoidAxisSelfTuning.EXECUTE := FALSE;
    END_IF;
    IF  g_bPlcResetBuffer THEN
      nMoveSelfTuningState := 20;
    END_IF;

  20:
      g_AntiRejection6Stop.Execute := TRUE;
      IF g_AntiRejection6Stop.Done  THEN
        g_AntiRejection6Stop.Execute := FALSE;
        nMoveSelfTuningState := 0;
      END_IF;
      IF g_AntiRejection6Stop.CommandAborted OR g_AntiRejection6Stop.Error THEN
        g_AntiRejection6Stop.Execute := FALSE;
        nMoveSelfTuningState := 0;
      END_IF;
    IF g_bPlcResetBuffer THEN
      g_AntiRejection6Stop.Execute := FALSE;
      nMoveSelfTuningState := 0;
    END_IF;
END_CASE;
IF g_bPlcResetBuffer THEN
  g_BeamAvoidAxisSelfTuning.EXECUTE := FALSE;
  g_bBeamAvoidAxisSelfTuningDone := FALSE;
  g_AntiRejection6Stop.Execute := FALSE;
  nMoveSelfTuningState := 0;
  bMoveSelfTuningStart := FALSE;
END_IF;
